@import url('');

:root {
  color-scheme: dark;
  --ink: #171b2f;
  --panel: #242a43;
  --panel-light: #303854;
  --cream: #f4efdc;
  --muted: #aeb6c9;
  --mint: #8ee3c0;
  --pink: #ff9cba;
  font-family: system-ui, sans-serif;
  font-size: 16px;
}

* { box-sizing: border-box; }
body {
  margin: 0;
  min-height: 100vh;
  padding: 40px 18px;
  display: grid;
  place-items: center;
  color: var(--cream);
  background-color: var(--ink);
  background-image: radial-gradient(#303854 1.5px, transparent 1.5px);
  background-size: 24px 24px;
}
button { font: inherit; }
.player {
  width: min(100%, 600px);
  padding: clamp(22px, 5vw, 38px);
  background: var(--panel);
  border: 3px solid #414966;
  box-shadow: 9px 9px 0 #0e1120;
}
.header { display: flex; gap: 18px; align-items: center; }
.pixel-mark {
  width: 60px;
  height: 60px;
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  color: var(--ink);
  background: var(--mint);
  border: 4px solid var(--cream);
  box-shadow: 4px 4px 0 var(--ink);
  font-size: 32px;
}
.eyebrow, .summary-label, .list-heading, .footer-note { letter-spacing: .12em; }
.eyebrow { margin: 0 0 4px; color: var(--mint); font-size: 12px; font-weight: 800; }
h1 { margin: 0; font-size: clamp(25px, 6vw, 34px); line-height: 1.15; }
.summary {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
  margin: 30px 0;
  padding: 18px;
  background: var(--ink);
  border: 2px solid var(--panel-light);
}
.summary > div { display: grid; gap: 5px; }
.summary-label { color: var(--muted); font-size: 11px; font-weight: 800; }
.summary strong { font-size: 19px; }
.list-heading { display: flex; justify-content: space-between; align-items: baseline; margin-bottom: 10px; }
.list-heading h2 { margin: 0; font-size: 13px; }
.list-hint { color: var(--muted); font-size: 10px; }
.playlist { list-style: none; margin: 0; padding: 0; display: grid; gap: 9px; }
.track {
  display: grid;
  grid-template-columns: 32px minmax(0, 1fr) auto;
  gap: 12px;
  align-items: center;
  min-height: 72px;
  padding: 10px 12px;
  background: var(--panel-light);
  border: 2px solid transparent;
}
.track-number { color: var(--mint); font-size: 14px; font-weight: 800; text-align: center; }
.track-copy { min-width: 0; }
.track-title { display: block; overflow-wrap: anywhere; font-weight: 750; }
.track-duration { display: block; margin-top: 4px; color: var(--muted); font-size: 14px; }
.track-actions { display: flex; gap: 5px; }
.icon-button {
  width: 40px;
  height: 40px;
  padding: 0;
  color: var(--cream);
  background: var(--ink);
  border: 2px solid #59617e;
  cursor: pointer;
  font-size: 18px;
}
.icon-button.remove { color: var(--pink); }
button { transition: transform .12s ease, background-color .12s ease, border-color .12s ease; }
button:hover { background-color: #3b4565; border-color: var(--mint); }
button:active { transform: translateY(2px); }
button:focus-visible { outline: 3px solid var(--pink); outline-offset: 3px; }
.shuffle-button {
  width: 100%;
  min-height: 52px;
  margin-top: 20px;
  color: var(--ink);
  background: var(--mint);
  border: 3px solid var(--cream);
  box-shadow: 4px 4px 0 var(--ink);
  cursor: pointer;
  font-weight: 850;
}
.shuffle-button:hover { background: #a4f2d1; border-color: white; }
.shuffle-button span { margin-right: 8px; font-size: 20px; }
.footer-note { margin: 18px 0 0; color: var(--muted); font-size: 12px; text-align: center; letter-spacing: .03em; }
@media (max-width: 420px) {
  body { padding: 18px 12px; }
  .track { grid-template-columns: 26px minmax(0, 1fr) auto; gap: 8px; padding: 9px 7px; }
  .track-actions { gap: 3px; }
  .icon-button { width: 36px; height: 40px; }
}

const initialSongs = [
  { title: 'Starlight Arcade', seconds: 194 },
  { title: 'Mossy Meadow', seconds: 238 },
  { title: 'Midnight Sprites', seconds: 167 },
  { title: 'Cloudtop Cruise', seconds: 221 },
  { title: 'Tiny Town Parade', seconds: 183 },
  { title: 'Save Point Sunset', seconds: 256 }
];

let songs = initialSongs.map(song => ({ ...song }));
const playlist = document.querySelector('#playlist');
const count = document.querySelector('#song-count');
const total = document.querySelector('#total-length');

function formatDuration(seconds) {
  const hours = Math.floor(seconds / 3600);
  const minutes = Math.floor((seconds % 3600) / 60);
  const remainder = seconds % 60;
  return `${hours}:${String(minutes).padStart(2, '0')}:${String(remainder).padStart(2, '0')}`;
}

function render() {
  playlist.replaceChildren();
  songs.forEach((song, index) => {
    const item = document.createElement('li');
    item.className = 'track';

    const number = document.createElement('span');
    number.className = 'track-number';
    number.textContent = String(index + 1).padStart(2, '0');
    number.setAttribute('aria-hidden', 'true');

    const copy = document.createElement('div');
    copy.className = 'track-copy';
    const title = document.createElement('span');
    title.className = 'track-title';
    title.textContent = song.title;
    const duration = document.createElement('span');
    duration.className = 'track-duration';
    duration.textContent = formatDuration(song.seconds);
    copy.append(title, duration);

    const actions = document.createElement('div');
    actions.className = 'track-actions';
    const up = makeButton('↑', `Move ${song.title} up`, 'up', index, index === 0);
    const down = makeButton('↓', `Move ${song.title} down`, 'down', index, index === songs.length - 1);
    const remove = makeButton('×', `Remove ${song.title}`, 'remove', index, false, 'remove');
    actions.append(up, down, remove);
    item.append(number, copy, actions);
    playlist.append(item);
  });

  const durationSeconds = songs.reduce((sum, song) => sum + song.seconds, 0);
  count.textContent = `${songs.length} ${songs.length === 1 ? 'song' : 'songs'}`;
  total.textContent = formatDuration(durationSeconds);
}

function makeButton(label, accessibleName, action, index, disabled, extraClass = '') {
  const button = document.createElement('button');
  button.type = 'button';
  button.className = `icon-button ${extraClass}`.trim();
  button.textContent = label;
  button.setAttribute('aria-label', accessibleName);
  button.disabled = disabled;
  if (disabled) button.setAttribute('aria-disabled', 'true');
  button.addEventListener('click', () => {
    if (action === 'remove') songs.splice(index, 1);
    if (action === 'up' && index > 0) [songs[index - 1], songs[index]] = [songs[index], songs[index - 1]];
    if (action === 'down' && index < songs.length - 1) [songs[index + 1], songs[index]] = [songs[index], songs[index + 1]];
    render();
  });
  return button;
}

document.querySelector('#shuffle').addEventListener('click', () => {
  for (let index = songs.length - 1; index > 0; index -= 1) {
    const swapIndex = Math.floor(Math.random() * (index + 1));
    [songs[index], songs[swapIndex]] = [songs[swapIndex], songs[index]];
  }
  render();
});

render();
